using OscVisualizer.Models;
using System.Collections.Generic;

namespace OscVisualizer.Services;

internal static class KamonTraces
{
    internal static bool TryAdd(int index, List<XYPoint> points)
    {
        if (index < 0 || index >= Data.Length || Data[index].Length == 0)
            return false;

        foreach (var trace in Data[index])
        {
            for (int i = 0; i < trace.Length; i++)
            {
                var a = trace[i];
                var b = trace[(i + 1) % trace.Length];
                points.Add(new XYPoint(a.x, a.y, 0.25));
                points.Add(new XYPoint(b.x, b.y, 0.8));
            }
        }
        return true;
    }

